  "Em vez de um bloco único, a resposta sai em bolhas separadas, espaçadas pelo mesmo ritmo anti-banimento do envio. O agente também é instruído a escrever em parágrafos curtos.": "Instead of a single block, the reply goes out in separate bubbles, spaced at the same anti-ban sending pace. The agent is also instructed to write in short paragraphs.",
