  "O que o agente pode fazer": "What the agent can do",
  "Ligue por jornada de trabalho. O agente só consegue fazer o que estiver ligado aqui — e o que estiver ligado, ele fará sozinho durante o atendimento.": "Enable by workflow. The agent can only do what is enabled here — and whatever is enabled, it will do on its own during the conversation.",
  "Quando ele entra em ação": "When it steps in",
  "Passar para uma pessoa": "Hand off to a person",
  "Deixar o agente chamar uma pessoa quando perceber que não é caso dele": "Let the agent call a person when it realizes a case isn't for it",
  "Pedir ajuda sem sair da conversa": "Ask for help without leaving the conversation",
  "Deixar o agente pedir uma tarefa a alguém e seguir conversando": "Let the agent assign a task to someone and keep chatting",
  "Diferente de passar a conversa: aqui o agente continua atendendo. Quando esbarra em algo que só uma pessoa resolve — aprovar um desconto, por exemplo — ele abre um pedido interno e retoma assim que for respondido.": "Unlike handing off the conversation: here the agent keeps assisting. When it runs into something only a person can resolve — approving a discount, for example — it opens an internal request and resumes as soon as it gets a reply.",
  "Follow-up": "Follow-up",
  "Retomar sozinho quem parou de responder, para o interessado não sumir sem ninguém perceber.": "Automatically follow up with anyone who stopped replying, so leads don't slip away unnoticed.",
