  "Em que negócios ele pode mexer": "Which deals it can touch",
  "Marque os funis que este assistente cuida. Ele conversa com qualquer cliente, mas só move, edita ou encerra negócio dos funis marcados aqui.": "Check the pipelines this assistant manages. It chats with any customer, but only moves, edits, or closes deals in the pipelines checked here.",
  "Você ainda não tem nenhum funil. Crie um em Funis para poder liberar o assistente.": "You don't have any pipelines yet. Create one under Pipelines to enable the assistant.",
  "(é para cá que vão as conversas novas)": "(new conversations go here)",
  "— ele não sabe organizar este funil ainda": "— it doesn't know how to organize this pipeline yet",
  "Sem nenhum funil marcado, ele conversa com os clientes normalmente, mas não mexe em negócio nenhum — nem move, nem encerra, nem marca.": "With no pipeline checked, it chats with customers normally, but doesn't touch any deals — it won't move, close, or tag them.",
  "Você marcou": "You checked",
  ", mas ninguém disse ao assistente o que cada etapa desse funil significa — ele vai atender e deixar os negócios parados onde estão.": ", but no one told the assistant what each stage of this pipeline means — it will assist customers and leave deals sitting where they are.",
  "funis em que ninguém disse ao assistente o que cada etapa significa — ele vai atender e deixar os negócios parados onde estão.": "pipelines where no one told the assistant what each stage means — it will assist customers and leave deals sitting where they are.",
  " Isso se configura em Configurações › Funis.": " You can configure this under Settings › Pipelines.",
  "As conversas novas viram negócio em": "New conversations become deals in",
  ", que não está marcado. O assistente vai atender e os negócios vão se acumular ali sem que ele possa organizá-los.": ", which isn't checked. The assistant will reply and deals will pile up there without it being able to organize them.",
