  "Antes de cada mensagem sair": "Before each message goes out",
  "O assistente escreve, e o sistema confere. São": "The assistant writes, and the system checks. There are",
  "verificações, nesta ordem — a primeira que barra interrompe as seguintes, e o assistente recebe de volta o motivo para reescrever.": "checks, in this order — the first one that blocks stops the rest, and the assistant gets the reason back to rewrite.",
  "Antes de o assistente ler": "Before the assistant reads",
  "Esta roda sobre a mensagem que chega, antes das outras — por isso aparece separada.": "This runs on incoming messages before the others — which is why it appears separately.",
