  "Em": "In",
  "delas o assistente tinha algo a registrar e nenhuma capacidade marcada para isso — o que resolve é marcar abaixo o que ele pode fazer.": "of them, the assistant had something to log and no capability checked for it — fix this by checking what it's allowed to do below.",
  "Deixar o agente organizar o sistema depois de cada conversa": "Let the agent organize the system after each conversation",
  "Quem conversa com o cliente é uma coisa; quem mantém o sistema em dia é outra. Separar os dois evita que o assistente comente com o cliente o que está fazendo por dentro — e é o que faz ele realmente registrar, em vez de só responder bem.": "Talking to the customer is one thing; keeping the system up to date is another. Separating the two keeps the assistant from telling the customer what it's doing behind the scenes — and ensures it actually logs things instead of just replying well.",
  "Com isto desligado:": "With this turned off:",
  "o assistente continua atendendo e o básico continua sendo registrado sozinho — a etapa do cliente, o retorno que ele prometeu e o histórico da conversa.": "the assistant keeps helping customers and the basics are still logged automatically — the customer's stage, any promised follow-up, and the conversation history.",
  "O que ele deixa de fazer é": "What it stops doing is",
  "decidir sobre a operação": "making operational decisions",
  ": abrir chamados, distribuir para a pessoa certa, organizar marcadores e etapas. Isso passa a ser trabalho de alguém do time.": ": opening tickets, routing to the right person, organizing tags and stages. That becomes a job for someone on the team.",
  "A inteligência que ele usa para organizar": "The intelligence it uses to organize",
  "Pode ser diferente da que conversa. Organizar o sistema é uma tarefa mais mecânica que atender uma pessoa — costuma sair bem com um modelo mais barato.": "It can be different from the one that chats. Organizing the system is more mechanical than helping a person — it usually works well with a cheaper model.",
  "A mesma que conversa": "Same as chat",
  "Usar a mesma que conversa": "Use the same as chat",
  "O que ele pode mexer no sistema": "What it can change in the system",
  "Esta lista é só deste papel — nada aqui é usado enquanto ele conversa com o cliente. Ligue por jornada de trabalho.": "This list is only for this role — nothing here is used while chatting with the customer. Enable by workflow.",
  "Sem nada marcado, ele ainda avisa você quando o assistente prometer algo a um cliente e ninguém cumprir — mas não consegue resolver sozinho.": "With nothing checked, it still alerts you when the assistant promises something to a customer and no one follows through — but it can't resolve it on its own.",
