  "O fluxo começa quando um negócio entra nesta etapa, por arrasto no quadro ou por automação. A entrada na fila leva poucos minutos, não é instantânea.": "The flow starts when a deal enters this stage, whether dragged on the board or moved by automation. Queuing takes a few minutes and isn't instant.",
  "O fluxo começa quando o agente abre um caso — o momento em que ele diz que precisa de uma pessoa. Não há o que escolher aqui: vale para qualquer caso desta conta.": "The flow starts when the agent opens a case — the moment it says it needs a person. There's nothing to select here: it applies to any case in this account.",
