  "A validação não terminou. Clique em revalidar para testar a chave agora.": "Validation didn't finish. Click revalidate to test the key now.",
  "O provedor recusou a chave. Confira se copiou inteira ou gere uma nova.": "The provider rejected the key. Make sure you copied all of it or generate a new one.",
  "O provedor limitou as chamadas desta chave. Tente de novo em alguns minutos.": "The provider rate-limited this key. Try again in a few minutes.",
  "O provedor está fora do ar. A chave pode estar certa; revalide mais tarde.": "The provider is down. The key might be valid; revalidate later.",
  "Não foi possível falar com o provedor a partir deste servidor. Revalide mais tarde.": "Couldn't reach the provider from this server. Revalidate later.",
  "Falha na validação": "Validation failed",
  "Pegar chave em": "Get key at",
  "O padrão recomendado para conversar com o cliente: é o que melhor segue instruções longas e usa as ferramentas do CRM.": "The recommended default for chatting with customers: best at following long instructions and using CRM tools.",
  "Necessário para transcrever áudio e para indexar o seu material — esses dois pontos usam tecnologia da OpenAI mesmo quando o resto está em outro provedor.": "Required for transcribing audio and indexing your content — both use OpenAI technology even when everything else runs on another provider.",
  "Alternativa com contexto muito longo e custo baixo para tarefas de classificação.": "Very long-context, low-cost alternative for classification tasks.",
  "Uma chave só dá acesso a centenas de modelos de dezenas de fabricantes, inclusive os gratuitos. É o caminho mais simples para experimentar sem abrir conta em cada provedor.": "A single key gives you access to hundreds of models from dozens of providers, including free ones. It's the easiest way to experiment without opening an account with each provider.",
