  "Atualização do caso": "Case update",
  "Um roteador entende o que o cliente quer e entrega a conversa para o agente certo — plugado em um número de WhatsApp.": "A router understands what the customer wants and hands the conversation to the right agent — plugged into a WhatsApp number.",
  "Novo roteador": "New router",
  "Um roteador entende o que o cliente quer e entrega a conversa para o agente certo — um número de vendas fala com quem quer comprar, um de suporte com quem já é cliente, tudo no mesmo WhatsApp. Crie um para o seu número e escolha quais agentes ele aciona.": "A router understands what the customer wants and hands the conversation to the right agent — a sales agent talks to buyers, a support agent talks to existing customers, all on the same WhatsApp number. Create one for your number and choose which agents it triggers.",
  "Criar meu primeiro roteador": "Create my first router",
  "Número removido": "Number removed",
  "Sem intenções configuradas": "No intents configured",
  "intenção": "intent",
  "intenções": "intents",
  "Roteador criado — agora escolha as intenções.": "Router created — now choose the intents.",
  "Escolha o número de WhatsApp que ele vai atender. Depois de criado, você define as intenções e para qual agente cada uma vai.": "Choose the WhatsApp number it will handle. Once created, you define the intents and which agent each one goes to.",
  "Número de WhatsApp": "WhatsApp number",
  "Só é possível ter um roteador ativo por número.": "You can only have one active router per number.",
  "Criar roteador": "Create router",
