  "Identificação": "Identification",
  "O número não pode ser trocado depois de criado — crie outro roteador para um número diferente.": "The number cannot be changed after creation — create another router for a different number.",
  "Ativo — está roteando as conversas deste número": "Active — routing conversations for this number",
  "Inativo — não roteia nada": "Inactive — not routing anything",
