  "Modelo do classificador": "Classifier model",
  "Automático — usa o provedor da organização": "Automatic — uses the organization's provider",
  "chave desta instalação": "key from this installation",
  "Nenhuma chave de IA utilizável nesta organização — cadastre uma em Agentes IA › Credenciais para poder escolher o modelo.": "No usable AI key in this organization — add one in AI Agents › Credentials to choose a model.",
  "Só aparecem modelos de provedores com chave cadastrada aqui. Se a conta do provedor estiver sem crédito, a identificação falha e tudo cai no fallback.": "Only models from providers with a key registered here are shown. If the provider account runs out of credit, identification fails and everything goes to the fallback.",
  "Se nenhuma intenção casar": "If no intent matches",
  "Agente de fallback": "Fallback agent",
  "Nenhum — responde com o atendimento padrão": "None — replies with default handling",
  "Quando a IA não tem certeza do que o cliente quer, ela chama este agente em vez de travar a conversa.": "When the AI isn't sure what the customer wants, it calls this agent instead of stalling the conversation.",
  "Intenções": "Intents",
  "Cada intenção descreve uma situação e diz qual agente deve assumir a conversa quando o cliente quer aquilo.": "Each intent describes a situation and specifies which agent should take over the conversation when that's what the customer wants.",
  "Intenção": "Intent",
  "Nenhuma intenção ainda. Sem intenções, toda conversa cai direto no agente de fallback (ou fica sem resposta automática, se você não escolher um).": "No intents yet. Without intents, every conversation goes straight to the fallback agent (or gets no automated reply if you don't pick one).",
  "O número volta a ser atendido pelos gatilhos normais dos agentes (sem roteamento por intenção). As intenções deste roteador são apagadas junto. Não é possível desfazer.": "The number goes back to being handled by the agents' normal triggers (without intent routing). This router's intents will also be deleted. This cannot be undone.",
