  "A IA nunca para por gasto. Você vê o número nesta tela e decide o que fazer.": "The AI never stops due to spend. You track the number on this screen and decide what to do.",
  "A IA para de responder ao chegar em": "The AI stops replying when it reaches",
  "A parada começa a valer": "The stop takes effect",
  "A parada começa a valer em": "The stop takes effect on",
  "A proteção de gasto está desligada nesta instalação (AI_BUDGET_ENFORCEMENT=off). O que estiver escolhido aqui não vale enquanto quem cuida do servidor não religar.": "Spend protection is turned off on this installation (AI_BUDGET_ENFORCEMENT=off). Whatever is selected here won't take effect until your server administrator turns it back on.",
  "Abrimos um aviso na Central de avisos. A IA continua respondendo normalmente.": "We posted an alert in the Notification Center. The AI keeps replying normally.",
  "Aguardando decisão": "Awaiting decision",
  "Aprendizado adicionado.": "Learning added.",
  "Aprendizado arquivado.": "Learning archived.",
  "Aprendizado reativado.": "Learning reactivated.",
  "Aprendizados": "Learnings",
  "Aprovada": "Approved",
  "Aprovar": "Approve",
  "Aprovar e ignorar viram registro — os dois. Quando você decidir a primeira, ela fica aqui.": "Both approving and ignoring are logged. Once you make your first decision, it shows up here.",
  "As conversas em andamento vão para a fila de atendimento humano — ninguém fica sem resposta, mas alguém precisa responder. Cada uma volta ao automático pelo botão \"Devolver ao automático\" no cabeçalho dela.": "Ongoing conversations move to the human support queue — no one is left unanswered, but someone needs to reply. Each one can be returned to automation using the \"Return to automation\" button in its header.",
  "Assuntos mais procurados": "Top topics",
  "Atendimentos com IA": "AI-handled conversations",
  "Até": "Up to",
  "Até lá, só avisamos.": "Until then, we only notify you.",
  "Avisamos ao passar de": "We notify you when it exceeds",
  "Avisar ao chegar em (% do limite)": "Notify when reaching (% of limit)",
  "Avisos que você marcar como resolvidos ficam aqui.": "Alerts you mark as resolved stay here.",
  "Cada linha aqui é uma coisa que está limitando seu agente, e o que fazer a respeito — às vezes você mesmo, às vezes quem cuida da sua instalação.": "Each row here is something holding your agent back and what to do about it — sometimes by you, sometimes by whoever manages your installation.",
  "Cada linha é uma coisa nova que o agente passou a saber, na ordem em que aconteceu.": "Each row is something new the agent learned, in the order it happened.",
