  "Enviar skill (.zip)": "Upload skill (.zip)",
  "Escolha o que acontece quando o gasto do mês chega no limite. Os valores são em dólar — é a moeda em que o provedor de IA cobra.": "Choose what happens when monthly spend hits the limit. Amounts are in US dollars — the currency AI providers bill in.",
  "Este ponto usa o modelo definido na versão publicada do agente.": "This item uses the model defined in the agent's published version.",
  "Ex.: Nunca prometa desconto sem confirmar com um humano. Horário de atendimento: 9h–18h, seg-sex. Sempre chame o cliente pelo primeiro nome.": "E.g.: Never promise a discount without confirming with a human. Support hours: 9am–6pm, Mon–Fri. Always call the customer by their first name.",
  "Ex.: Não oferecer frete grátis no primeiro contato": "E.g.: Don't offer free shipping on first contact",
  "Execuções de IA": "AI runs",
  "Fatos e correções pontuais que os agentes também levam em conta — adicionados à mão ou aprendidos automaticamente pelo sistema a partir de conversas reais.": "Specific facts and corrections that agents also take into account — added manually or learned automatically by the system from real conversations.",
  "Gasto de": "Spend for",
  "Habilidades especializadas que seus agentes carregam só quando a conversa pede — instale prontas do catálogo ou envie a sua.": "Specialized skills your agents load only when the conversation calls for them — install ready-made ones from the catalog or upload your own.",
