  "Memória da IA": "AI Memory",
  "Mensagem técnica do provedor": "Provider technical message",
  "Mostrando só as falhas": "Showing failures only",
  "Mudanças de passo no atendimento": "Step changes in conversation",
  "Negócios fechados pelo agente": "Deals won by the agent",
  "Negócios perdidos pelo agente": "Deals lost by the agent",
  "Nenhum aprendizado ainda. Use \"+ Novo aprendizado\" para ensinar algo que os agentes devem lembrar em toda conversa — ou aguarde o sistema sugerir aprendizados automaticamente a partir do atendimento real.": "No learnings yet. Use \"+ New learning\" to teach something agents should remember in every conversation — or wait for the system to suggest learnings automatically from real conversations.",
  "Nenhum aprendizado arquivado.": "No archived learnings.",
  "Nenhum aviso em aberto": "No open alerts",
  "Nenhum aviso resolvido": "No resolved alerts",
  "Nenhuma conversa foi classificada por assunto. Os assuntos são os que você cadastra no roteador do seu número.": "No conversations were classified by topic. Topics are the intents you set up in your number's router.",
  "Nenhuma conversa foi encaminhada. Isso só acontece em números que têm um roteador configurado — sem ele, tudo cai no atendimento padrão.": "No conversations were routed. This only happens on numbers with a configured router — without one, everything goes to default handling.",
  "Nenhuma decisão registrada ainda": "No decisions recorded yet",
  "Nenhuma execução ainda. Assim que o agente atender alguém, aparece aqui.": "No runs yet. As soon as the agent assists someone, it shows up here.",
  "Nenhuma falha": "No failures",
  "Nenhuma falha registrada.": "No failures recorded.",
  "Nenhuma habilidade foi usada neste período, então não há o que ranquear.": "No skills were used during this period, so there's nothing to rank.",
  "Nenhuma habilidade foi usada. Ou o agente ainda não tem nenhuma instalada, ou as conversas do período não pediram nenhuma.": "No skills were used. Either the agent doesn't have any installed yet, or the conversations in this period didn't need any.",
  "Nenhuma proposta esperando você": "No proposals waiting for you",
  "Nenhuma skill instalada ainda. Instale uma pronta do catálogo abaixo ou envie a sua em \"Enviar skill (.zip)\".": "No skills installed yet. Install a ready-made one from the catalog below or upload your own via \"Upload skill (.zip)\".",
  "Nenhuma skill nova no catálogo — você já instalou tudo que a plataforma oferece hoje.": "No new skills in the catalog — you've already installed everything the platform offers today.",
  "Nenhuma versão publicada ainda": "No published version yet",
  "Nesta instalação a proteção só avisa (AI_BUDGET_ENFORCEMENT=avisar): mesmo com \"Parar a IA\" escolhido, ela vai continuar respondendo.": "On this installation, protection only notifies (AI_BUDGET_ENFORCEMENT=avisar): even with \"Stop the AI\" selected, it will keep replying.",
  "Novo aprendizado": "New learning",
  "Não consegui carregar a configuração de IA": "Couldn't load AI configuration",
  "Não consegui carregar as execuções": "Couldn't load runs",
  "Não conseguimos carregar os números agora. Recarregue a página em alguns instantes — se continuar assim, avise quem cuida da sua instalação.": "We couldn't load the numbers right now. Reload the page in a few moments — if it keeps happening, let your installation administrator know.",
  "O agente não consultou seus materiais. Ou não há nada publicado na base de conhecimento, ou as conversas não chegaram a precisar.": "The agent didn't check your materials. Either nothing is published in the knowledge base, or the conversations didn't need it.",
  "O catálogo deste provedor ainda não foi baixado. Digite o identificador do modelo como o provedor o nomeia — a lista completa aparece sozinha depois da primeira sincronização.": "This provider's catalog hasn't been downloaded yet. Type the model identifier as named by the provider — the full list appears automatically after the first sync.",
  "O que aconteceu:": "What happened:",
  "O que ele fez": "What it did",
  "O que está travando": "What's holding it back",
  "O que fazer:": "What to do:",
  "O que mudou no resultado": "What changed in your results",
  "O que o agente deve saber": "What the agent should know",
  "O que o assistente precisou escalar para o time: conexões caídas, tarefas que falharam, atendimentos passados a humanos.": "What the assistant had to escalate to the team: dropped connections, failed tasks, conversations handed off to humans.",
  "O que os clientes mais quiseram, segundo o que o roteador entendeu de cada conversa.": "What customers asked for most, based on what the router understood from each conversation.",
  "O que seu agente aprendeu": "What your agent learned",
  "O que seu agente aprendeu no período, o que ele fez com isso, o que mudou no seu resultado — e o que ainda está travando.": "What your agent learned during the period, what it did with it, what changed in your results — and what's still holding it back.",
  "O que seus agentes já sabem fazer além da conversa comum — cada skill só entra em ação quando o assunto pede.": "What your agents already know how to do beyond regular chat — each skill only kicks in when the topic calls for it.",
  "O que você pagou aos provedores de IA para tudo isto acontecer.": "What you paid AI providers for all of this to happen.",
  "O texto-base que qualquer agente de IA lê antes de responder — como a \"política da casa\" que todo atendente novo teria que decorar.": "The baseline text every AI agent reads before replying — like the \"house rules\" every new team member would have to memorize.",
  "O trabalho do dia a dia: quantas vezes ele usou cada recurso que você deu a ele.": "Day-to-day work: how many times it used each resource you gave it.",
  "Ocultar": "Hide",
  "Onde o agente mais precisou de conhecimento especializado.": "Where the agent needed specialized knowledge the most.",
  "Orçamento de IA": "AI Budget",
  "Orçamento mensal de IA": "Monthly AI budget",
  "Para avisar ou parar no limite, ele precisa ser de pelo menos": "To notify or stop at the limit, it must be at least",
  "Para personalizar uma skill instalada, basta reenviar um .zip com o mesmo nome — a sua versão passa a valer no lugar da do catálogo. Não há editor dentro do sistema nesta fase.": "To customize an installed skill, just re-upload a .zip with the same name — your version replaces the catalog one. There is no built-in editor at this stage.",
  "Parar a IA ao chegar em": "Stop the AI when it reaches",
