  "Provedor": "Provider",
  "Próximos passos que o assistente sugeriu e esperam sua decisão. Aprovar e ignorar são registrados — ignorar é uma decisão, não a falta dela.": "Next steps suggested by the assistant awaiting your decision. Both approving and ignoring are logged — ignoring is a decision, not the lack of one.",
  "Publicada em": "Published on",
  "Publicar material": "Publish material",
  "Publicar uma regra": "Publish a rule",
  "Publicar versão": "Publish version",
  "Quando isso acontecer, as conversas em andamento vão para a fila de atendimento humano e voltam ao automático uma a uma, pelo cabeçalho de cada conversa.": "When this happens, ongoing conversations move to the human support queue and return to automation one by one from each conversation's header.",
  "Quando o assistente precisar de você, o aviso aparece aqui.": "When the assistant needs you, the alert shows up here.",
  "Quando o assistente sugerir um próximo passo, ele aparece aqui — e some daqui assim que você decidir.": "When the assistant suggests a next step, it shows up here — and disappears as soon as you decide.",
  "Quantas vezes o agente foi procurar a resposta no que você escreveu, em vez de improvisar.": "How many times the agent looked up the answer in what you wrote instead of improvising.",
  "Quantas vezes o agente puxou uma habilidade especializada para dar conta da conversa.": "How many times the agent pulled in a specialized skill to handle the conversation.",
