  "Quanto a inteligência artificial custou, quantos atendimentos ela fez, quanto demorou para responder e quantas vezes precisou chamar uma pessoa — nos últimos 30 dias.": "How much the AI cost, how many conversations it handled, how long it took to reply, and how many times it had to bring in a person — over the last 30 days.",
