  "Sem dados no período": "No data in period",
  "Sem limite definido — a IA não vai parar sozinha por gasto.": "No limit set — the AI won't stop on its own due to spend.",
  "Seu agente ainda não aprendeu nada neste período. Ele aprende de três jeitos: você publica uma regra na Memória da IA, aprova uma sugestão de melhoria na aba Propostas do agente, ou instala uma habilidade em Skills da IA.": "Your agent hasn't learned anything during this period yet. It learns in three ways: you publish a rule in AI Memory, approve an improvement suggestion in the agent's Proposals tab, or install a capability in AI Skills.",
