  "Nome do sistema": "System name",
  "Deixe em branco para voltar ao nome padrão. Este nome já aparece no título da aba do navegador, nos menus laterais, nos e-mails que o sistema envia (para as empresas que não definiram um nome próprio), no aplicativo de verificação em duas etapas e no arquivo de códigos de recuperação que o usuário baixa. Ainda NÃO chega às telas de entrada e cadastro nem às da configuração inicial: essas continuam com o nome gravado no arquivo de instalação do servidor até a próxima atualização da stack.": "Leave blank to restore the default name. This name already appears in the browser tab title, sidebar menus, emails sent by the system (for companies that haven't set their own name), the two-step verification app, and the recovery codes file downloaded by the user. It does NOT yet reach the sign-in, sign-up, or initial setup screens: those keep the name stored in the server installation file until the next stack update.",
  "Cor da marca": "Brand color",
  "Escolher a cor visualmente": "Pick color visually",
  "Use um código de cor como #7a5cd6.": "Use a color code like #7a5cd6.",
  "Deixe em branco para voltar à cor padrão do sistema.": "Leave blank to restore the default system color.",
  "A partir da sua cor o sistema monta esta escala e escolhe, dentro dela, o tom que vai nos botões:": "From your color, the system builds this scale and picks the shade used for buttons:",
  "No modo escuro o sistema usa naturalmente um tom mais claro da escala, para a cor não se perder no fundo escuro.": "In dark mode, the system naturally uses a lighter shade from the scale so the color doesn't get lost against the dark background.",
  "Sem cor definida, o sistema usa a cor padrão dele.": "When no color is set, the system uses its default color.",
