  "Desde": "Since",
  "o sistema voltou a usar as cores padrão dele.": "the system reverted to its default colors.",
  "Salvar uma cor válida aqui apaga este alerta.": "Saving a valid color here clears this alert.",
  "De onde vem cada coisa": "Where each value comes from",
  "Logo": "Logo",
  "O logo ainda é trocado no arquivo de instalação do servidor. Esta tela mostra de onde ele vem para que o valor não pareça ter sumido.": "The logo is still changed in the server installation file. This screen shows where it comes from so the value doesn't appear to be missing.",
  "O texto em cima dos botões": "Text on buttons",
  "Quanto maior o número, mais fácil de ler. AA é o mínimo recomendado internacionalmente para texto.": "The higher the number, the easier it is to read. AA is the internationally recommended minimum for text.",
  "No modo claro": "In light mode",
  "No modo escuro": "In dark mode",
  "O que o sistema ajustou": "What the system adjusted",
  "Nada foi ajustado — a escala acima mostra onde a sua cor entra.": "Nothing was adjusted — the scale above shows where your color fits.",
  "Do jeito que está, esta cor não chegaria à tela: o sistema continuaria com as cores padrão dele.": "As is, this color wouldn't reach the screen: the system would keep its default colors.",
  "Logo atualizado.": "Logo updated.",
  "Logo removido.": "Logo removed.",
  "PNG ou JPG, até": "PNG or JPG, up to",
  "KB. Prefira fundo transparente. SVG não é aceito: ele pode executar código quando aberto direto pelo endereço da imagem.": "KB. Transparent background preferred. SVG is not accepted: it can execute code when opened directly via the image URL.",
  "Como o logo aparece nas duas aparências do sistema:": "How the logo looks in both system themes:",
  "Sem logo próprio, o sistema usa o logo": "Without a custom logo, the system uses the logo",
  "Assim ele aparece:": "How it looks:",
  "O valor gravado para a cor não está na forma que o sistema entende.": "The stored color value is not in a format the system understands.",
  "A cor gravada não é um código de cor válido.": "The stored color is not a valid color code.",
  "A cor foi gravada por uma versão mais nova do sistema, e esta não sabe lê-la.": "The color was saved by a newer version of the system, and this version cannot read it.",
  "A cor foi salva por outra versão do sistema. Ela continua valendo — esta versão recalcula os tons a partir dela.": "The color was saved by another version of the system. It still applies — this version recalculates the shades from it.",
  "Esta versão do sistema não sabe onde aplicar a cor gravada, então ela não pinta a interface.": "This version of the system doesn't know where to apply the stored color, so it doesn't style the interface.",
  "A cor está guardada só como identidade: ela aparece no logo, mas não pinta os botões.": "The color is kept for identity only: it appears in the logo, but doesn't style the buttons.",
  "O cálculo dos tons a partir dessa cor não terminou.": "Shade calculation from this color did not finish.",
  "Sua cor é um tom neutro (cinza, preto ou branco), e uma cor assim não destaca nada na tela. Os botões seguem com a cor padrão do sistema, e a sua fica reservada ao logo.": "Your color is a neutral tone (gray, black, or white), which doesn't stand out on screen. Buttons keep the system default color, and yours is reserved for the logo.",
  "Não existe tom desta cor que deixe todos os elementos legíveis. Alguns detalhes — como o contorno que marca o campo em foco — ficam difíceis de enxergar.": "No shade of this color leaves all elements readable. Some details — such as the focus ring around active fields — become hard to see.",
  "A verificação de segurança barrou o resultado antes de ele chegar à tela, e a marca não foi aplicada.": "The security check blocked the result before it reached the screen, and the branding was not applied.",
  "O sistema recusou a cor gravada por um motivo que esta versão não sabe explicar.": "The system rejected the stored color for a reason this version cannot explain.",
  "A sua cor original continua no logo e nos destaques.": "Your original color remains on the logo and highlights.",
  "Algum campo não está no formato esperado.": "A field is not in the expected format.",
  "Sua sessão expirou. Entre de novo para salvar.": "Your session expired. Sign in again to save.",
  "Só quem administra a instalação pode mudar a marca.": "Only installation administrators can change the branding.",
  "Sua sessão expirou. Entre de novo para trocar o logo.": "Your session expired. Sign in again to change the logo.",
