  "Confirme o segundo fator nesta sessão e tente de novo.": "Confirm the second factor in this session and try again.",
  "Campo 'escopo' inválido.": "Invalid 'scope' field.",
  "O logo precisa ter até 512 KB. Arquivo maior vai inteiro para o navegador em toda página.": "The logo must be up to 512 KB. Larger files are sent in full to the browser on every page.",
  "SVG não é aceito como logo: ele pode executar código quando aberto direto do endereço da imagem. Exporte o mesmo arquivo em PNG (fundo transparente) ou JPG.": "SVG is not accepted as a logo: it can execute code when opened directly from the image URL. Export the same file as a PNG (transparent background) or JPG.",
