  "Oi {{nome}}, tudo bem?": "Hi {{nome}}, how are you?",
  "Respeitamos a janela de envio e o limite diário configurados para esse número em Conexões — fora da janela, a mensagem espera a próxima.": "We respect the sending window and daily limit configured for this number in Connections — outside the window, the message waits for the next one.",
