  "O que a IA deve fazer com os dados": "What the AI should do with the data",
  "Ex.: Agradeça o interesse citando o segmento que a pessoa informou, mostre em uma frase como a gente resolve a dificuldade que ela descreveu, e pergunte qual o melhor horário para conversar.": "E.g.: Thank them for their interest mentioning the industry they provided, show in one sentence how we solve the challenge they described, and ask for the best time to chat.",
  "O agente já sabe que é a PRIMEIRA mensagem, logo depois de a pessoa preencher o formulário, e recebe todos os campos que ela respondeu. Aqui você diz o que fazer com eles — quanto mais concreto, melhor a mensagem.": "The agent already knows this is the FIRST message right after the person fills out the form, and receives all the fields they submitted. Here you tell it what to do with them — the more specific, the better the message.",
