  "Este número é usado desde": "This number has been in use since",
  "A conexão pode ser nova sem que o número seja. O aquecimento conta a idade do NÚMERO — em branco, ele é tratado como recém-criado e começa liberando pouco por dia. Uma data já salva não some se você limpar o campo: para mudá-la, informe outra.": "The connection may be new even if the number isn't. Warm-up counts the age of the NUMBER — if left blank, it's treated as newly created and starts by allowing only a few messages per day. A saved date won't disappear if you clear the field: to change it, enter another date.",
  "Este número já está aquecido — pular o aquecimento": "This number is already warmed up — skip warm-up",
  "Vale só o teto diário abaixo. Use apenas se o número já envia há semanas: pular o aquecimento num número novo é o caminho mais rápido para o bloqueio.": "Only the daily cap below will apply. Use only if the number has been sending messages for weeks: skipping warm-up on a new number is the fastest way to get banned.",
  "Número com": "Number with",
  "dia(s) de uso — já formado. Vale só o teto diário abaixo.": "day(s) of use — fully warmed up. Only the daily cap below applies.",
  "Hoje o aquecimento libera": "Today warm-up allows",
  "envio(s) — o número tem": "send(s) — the number has",
  "dia(s) de uso. Enquanto esse número for menor que o teto diário, é ELE que limita, e mexer no teto diário não muda nada.": "day(s) of use. As long as this allowance is lower than the daily cap, IT is the active limit, and changing the daily cap has no effect.",
  "Janela de envio (horário local)": "Sending window (local time)",
  "Hora de início da janela": "Window start time",
  "h até": "to",
  "Hora de fim da janela": "Window end time",
  "O assistente só envia mensagens dentro desta janela. Fora dela, a resposta fica agendada para a próxima abertura — você vê o motivo na conversa.": "The assistant only sends messages within this window. Outside of it, replies are scheduled for the next opening — you can see the reason in the conversation.",
  "Enviar aos domingos": "Send on Sundays",
  "Ligado por padrão: quem escreve no domingo espera resposta no domingo. Desligue se você faz prospecção ativa e prefere não incomodar no fim de semana.": "On by default: people who message on Sunday expect a reply on Sunday. Turn off if you run outbound prospecting and prefer not to bother people on weekends.",
  "Ritmo entre envios (segundos)": "Pacing between sends (seconds)",
  "Intervalo mínimo entre envios em segundos": "Minimum interval between sends in seconds",
  "+ variação de até": "+ random variation up to",
  "Variação aleatória máxima em segundos": "Maximum random variation in seconds",
  "Intervalo mínimo entre mensagens do mesmo número, mais uma variação aleatória — ritmo cravado parece robô para o WhatsApp.": "Minimum interval between messages from the same number, plus a random variation — a fixed rhythm looks like a bot to WhatsApp.",
  "Teto diário de envios": "Daily sending cap",
  "sem teto definido": "no cap set",
  "Teto diário de mensagens": "Daily message cap",
  "Máximo de mensagens que este número envia por dia. Números novos também respeitam o aquecimento automático abaixo, o que for menor.": "Maximum messages this number sends per day. New numbers also respect the automatic warm-up below, whichever is lower.",
  "Fuso horário IANA": "IANA time zone",
  "Usar o padrão": "Use default",
  "A janela de envio é avaliada neste fuso (ex.: America/Sao_Paulo).": "The sending window is evaluated in this time zone (e.g., America/Sao_Paulo).",
  "Aquecimento automático de número novo": "Automatic warm-up for new numbers",
  "a partir de": "from",
  "dias: sem limite de aquecimento": "days: no warm-up limit",
  "dias: até": "days: up to",
  "dia": "day",
