  "Conectar por": "Connect via",
  "Um número oficial (WhatsApp Business) conectado através do seu provedor. As mensagens entram e saem pelo CRM, e os modelos aprovados são os mesmos da sua conta.": "An official number (WhatsApp Business) connected through your provider. Messages flow in and out through the CRM, and approved templates are the same ones from your account.",
