  "O serviço do WhatsApp não está configurado.": "The WhatsApp service is not configured.",
  "Faltam o endereço e a chave do serviço (": "The service address and key (",
  ") nas variáveis de ambiente desta instalação. Enquanto isso, não dá para conectar, reconectar nem excluir os números pareados por QR — excluir um número também o desconecta do aparelho, e sem o serviço isso não acontece.": ") are missing from this installation's environment variables. Until configured, you cannot connect, reconnect, or delete QR-paired numbers — deleting a number also unlinks it from the phone, which cannot happen without the service.",
  "Se você roda tudo na mesma máquina, o container sobe com": "If you run everything on the same machine, the container starts with",
  ". Já apareceu aqui o caso oposto: o container no ar e o endereço configurado apontando para um lugar que não existe — subir o container de novo não conserta isso.": ". We've also seen the opposite case: the container is running, but the configured address points somewhere that doesn't exist — restarting the container won't fix that.",
  "Esta instalação está com o banco atrasado.": "This installation's database is out of date.",
