  "Conectar Claude Code ou Codex": "Connect Claude Code or Codex",
  "Liga o seu Claude Code ou Codex ao Atenza. Ele passa a ler e preencher o CRM e pode atender os seus clientes no WhatsApp enquanto estiver aberto no seu computador.": "Connects your Claude Code or Codex to Atenza. It can read and update the CRM and assist your customers on WhatsApp while running on your computer.",
  "Gerar conexão": "Generate connection",
  "Chave secreta do App (App Secret)": "App Secret",
  "No painel da Meta: Configurações do app › Básico › Chave secreta do app": "In the Meta dashboard: App settings › Basic › App secret",
  "É com ela que conferimos que as mensagens vieram mesmo da Meta. Guardada cifrada.": "We use this to verify that messages genuinely came from Meta. Stored encrypted.",
  "Modo teste ligado.": "Test mode enabled.",
  "Modo teste desligado.": "Test mode disabled.",
  "Testar pelo meu próprio número": "Test with my own number",
  "Com isto ligado, o que você escreve no chat com você mesmo no WhatsApp conta como mensagem de cliente, e a resposta aparece ali. Desligue depois do teste.": "When enabled, messages you send to yourself on WhatsApp count as customer messages, and replies appear right there. Turn this off after testing.",
  "Ligado": "On",
  "Desligado": "Off",
  "1. Claude Code — cole no terminal": "1. Claude Code — paste in terminal",
