  "2. Para ele atender os clientes — cole dentro do Claude Code": "2. To let it assist customers — paste inside Claude Code",
  "Antes de deixar ele atender, pause o agente interno em Agentes de IA — senão o cliente recebe duas respostas. Ele só responde enquanto o Claude Code ou o Codex estiver aberto.": "Before letting it reply to customers, pause the built-in agent in AI Agents — otherwise the customer will get two replies. It only responds while Claude Code or Codex is open.",
