  "Pular tudo (DEV)": "Skip all (DEV)",
  "Como se chama o seu negócio?": "What's your business called?",
  "É o nome que aparece para o seu time e nos relatórios. Pode ser clínica, loja, escritório — o que for seu.": "This is the name shown to your team and in reports. It can be a clinic, store, office — whatever is yours.",
  "O que vocês fazem?": "What do you do?",
  "Ex.: clínica odontológica, ou venda de roupa fitness pelo WhatsApp": "E.g., dental clinic, or selling activewear over WhatsApp",
  "Uma linha basta. É com isso que seu funcionário aprende com quem ele está falando — e que a gente monta o quadro de clientes do seu jeito.": "One line is enough. This is how your assistant learns who they're talking to — and how we tailor the customer board to your business.",
