  "Não consegui gerar outro código. Tente de novo em alguns segundos.": "Could not generate another code. Try again in a few seconds.",
  "Não consegui falar com o servidor. Confira sua conexão e tente de novo.": "Could not reach the server. Check your connection and try again.",
  "Como você já usa esse número?": "How do you currently use this number?",
  "Existe mais de um jeito de ter WhatsApp para empresa, e cada um conecta de um jeito. Se você nunca ouviu falar dos outros dois, é o primeiro.": "There's more than one way to use WhatsApp for business, and each connects differently. If you've never heard of the other two, pick the first one.",
  "Leio um código com o celular": "I scan a QR code with my phone",
  "É assim para quase todo mundo. Você abre o WhatsApp no celular que vai atender e aponta para um código que aparece aqui.": "This is how most people do it. You open WhatsApp on the phone that handles messages and point it at a code shown here.",
  "Tenho conta oficial na Meta": "I have an official Meta account",
  "Você cadastrou o número na Meta e tem as credenciais em mãos. Não usa o celular para conectar.": "You registered the number with Meta and have your credentials ready. You don't use a phone to connect.",
  "Contrato de um provedor parceiro": "I use a partner provider",
  "Uma empresa parceira cuida do seu WhatsApp e te deu uma chave de acesso.": "A partner company manages your WhatsApp and gave you an access key.",
  "Este servidor ainda não está pronto para RECEBER por este caminho.": "This server isn't ready to RECEIVE messages through this method yet.",
  "Dá para conectar e já enviar, mas as respostas do cliente não vão chegar até quem instalou o sistema completar uma configuração no servidor. Se você quer atender hoje, o caminho do código com o celular funciona agora — e dá para trocar depois, sem perder nada.": "You can connect and start sending now, but customer replies won't arrive until whoever installed the system finishes a server configuration. If you want to start assisting customers today, scanning the QR code with your phone works right now — and you can switch later without losing anything.",
  "O WhatsApp desta instalação ainda não subiu.": "WhatsApp for this installation hasn't started yet.",
  "Ele roda no seu próprio servidor. Dá para seguir sem ele agora e conectar o número depois, em": "It runs on your own server. You can continue without it for now and connect your number later in",
  "Canais › Conexões": "Channels › Connections",
  "seu funcionário fica pronto de qualquer jeito, só não terá por onde atender ainda.": "your assistant will be ready either way — they just won't have a channel to reply on yet.",
  "Não consegui carregar o código agora. Ele deve reaparecer sozinho em instantes — se não aparecer, gere outro abaixo.": "Could not load the code right now. It should reappear automatically in a moment — if it doesn't, generate a new one below.",
  "Código QR para conectar o WhatsApp": "QR code to connect WhatsApp",
  "Conectado! Avançando…": "Connected! Moving on…",
