  "O serviço de WhatsApp desta instalação não respondeu. Ele roda no seu servidor, junto com o resto do sistema — quem instalou consegue religá-lo.": "The WhatsApp service for this installation didn't respond. It runs on your server alongside the rest of the system — whoever installed it can restart it.",
