  "Como ele vai se chamar": "What they'll be called",
  "É o nome que aparece para o seu time. O cliente vê só a conversa.": "This is the name shown to your team. The customer only sees the conversation.",
  "O jeito dele falar": "How they speak",
  "As regras da casa (opcional)": "House rules (optional)",
  "Nunca prometa desconto sem confirmar com uma pessoa.": "Never promise a discount without confirming with a person.",
  "Horário de atendimento: 9h às 18h, de segunda a sexta.": "Business hours: 9 AM to 6 PM, Monday through Friday.",
  "Sempre chame o cliente pelo primeiro nome.": "Always address the customer by their first name.",
  "O que vale para qualquer atendimento aqui. Pode deixar em branco agora e escrever depois — ele aprende com você ao longo do tempo.": "Rules that apply to every conversation here. You can leave this blank now and fill it in later — they learn from you over time.",
  "Ele já vem sabendo": "They already know how to",
  "E nunca vai fazer": "And will never",
