  "Copiar link": "Copy link",
  "Tudo pronto!": "All set!",
  "Seu funcionário está montado. Daqui em diante é só acompanhar.": "Your assistant is ready. From here on, just follow along.",
  "Seu funcionário já está de pé. O que ficou para depois continua te esperando.": "Your assistant is up and running. Anything you saved for later is still waiting for you.",
  "você pulou": "you skipped",
