  "O que mais tem aqui": "What else is here",
  "Você não precisa mexer em nada disso agora. É só para saber que existe.": "You don't need to touch any of this right now. Just so you know it's there.",
  "Como funciona": "How it works",
  "Finalizando...": "Finishing up...",
  "Começar a usar": "Get started",
  "As conversas": "Conversations",
  "É aqui que as conversas chegam, com você e ele atendendo lado a lado.": "This is where conversations arrive, with you and your assistant working side by side.",
  "O cliente manda uma mensagem no WhatsApp": "A customer sends a message on WhatsApp",
  "Ele responde sozinho, seguindo as regras da casa que você escreveu": "They reply automatically, following the house rules you wrote",
  "Se você entrar na conversa, ele sai da frente e deixa você atender": "If you jump into the conversation, they step back and let you take over",
  "O quadro de clientes": "The customer board",
  "Cada cliente vira um card, e ele mesmo move o card conforme a conversa anda.": "Each customer becomes a card, and your assistant moves it automatically as the conversation progresses.",
  "Cada cliente vira um cartão, na primeira coluna": "Each customer becomes a card in the first column",
  "Conforme a conversa avança, ele move o cartão de coluna sozinho": "As the conversation progresses, they move the card across columns automatically",
  "Você arrasta o cartão na mão quando quiser — o quadro é seu": "You can drag any card manually whenever you want — the board is yours",
  "Voltar a falar com quem sumiu": "Following up with people who went quiet",
  "Para nenhum cliente sumir no silêncio — ele volta a falar sozinho, na hora certa.": "So no customer slips through the cracks — they follow up automatically at the right time.",
  "O cliente para de responder no meio da conversa": "The customer stops replying mid-conversation",
  "Depois do tempo que você definir, ele manda uma mensagem puxando o assunto": "After the delay you set, they send a message to check back in",
  "Se o cliente responder, o retorno para na hora — ninguém é perseguido": "If the customer replies, follow-ups stop immediately — nobody gets hounded",
  "Se o cliente pedir para parar, ele para e não volta a escrever": "If the customer asks to stop, they stop and never message again",
  "E você pode pausar, adiar, pular um passo ou cancelar quando quiser": "And you can pause, snooze, skip a step, or cancel whenever you like",
  "O que está esfriando": "What's going cold",
  "Quem esfriou e ainda está aberto, para você agir antes de perder.": "Deals that went cold and are still open, so you can act before losing them.",
  "Ele observa há quanto tempo cada negócio em aberto não tem resposta": "They track how long each open deal has gone without a reply",
  "Os que estão esfriando sobem para o topo desta lista": "Deals that are going cold rise to the top of this list",
  "Você decide quem merece um empurrão seu, em vez de descobrir tarde demais": "You decide who needs a nudge from you, instead of finding out too late",
  "Quando ele pede ajuda": "When they ask for help",
  "Quando ele trava em algo que só uma pessoa resolve, o pedido aparece aqui.": "When they get stuck on something only a person can handle, the request shows up here.",
  "Ele encontra algo que não pode decidir sozinho — um desconto, uma exceção, um caso estranho": "They run into something they can't decide alone — a discount, an exception, an unusual case",
  "Em vez de inventar, ele para e abre um pedido aqui": "Instead of guessing, they stop and open a request here",
  "Você decide, e ele volta a andar com a sua resposta": "You decide, and they pick back up with your answer",
  "As ideias dele": "Their ideas",
  "Com o tempo ele sugere as próprias melhorias — e você decide se entram.": "Over time, they suggest their own improvements — and you decide whether to apply them.",
  "Ele acompanha os próprios atendimentos e percebe o que poderia ir melhor": "They review their own conversations and spot what could go better",
  "Escreve a sugestão aqui, em português, e espera": "They write the suggestion here in plain language and wait",
