  "Importar contatos de planilha": "Import contacts from spreadsheet",
  "Envie um arquivo .csv com cabeçalho — colunas reconhecidas: nome, telefone, email, cpf, nascimento, tags. Excel: use “Salvar como” → “CSV UTF-8”. Máximo de 500 linhas por arquivo.": "Upload a .csv file with a header row — recognized columns: nome, telefone, email, cpf, nascimento, tags. In Excel: use “Save As” → “CSV UTF-8”. Maximum of 500 rows per file.",
  "Este arquivo não parece ser um CSV de texto. No Excel use “Salvar como” → “CSV UTF-8 (delimitado por vírgulas)”.": "This file does not appear to be a text CSV. In Excel, use “Save As” → “CSV UTF-8 (Comma delimited)”.",
