  "Google Agenda desta instalação": "Google Calendar for this installation",
  "Com estas duas informações, quem atende consegue conectar a agenda pessoal do Google e ver os compromissos do CRM lá. Elas valem para a instalação inteira — cada pessoa conecta a conta dela depois, sozinha.": "With these two details, team members can connect their personal Google Calendar and see CRM appointments there. They apply to the entire installation — each person connects their own account afterward.",
  "Endereço de retorno": "Redirect URI",
  "Já existe uma chave cadastrada. Deixe em branco para mantê-la, ou digite uma nova para substituir.": "A key is already saved. Leave blank to keep it, or enter a new one to replace it.",
  "Ela é guardada cifrada e nunca volta a aparecer nesta tela.": "It is stored encrypted and will never be shown on this screen again.",
  "Esta instalação já tem as credenciais no arquivo de configuração do servidor. O que você salvar aqui passa a valer no lugar delas; apagar o que está aqui faz o sistema voltar a usar as do arquivo.": "This installation already has credentials in the server configuration file. What you save here overrides them; clearing this field falls back to the file credentials.",
  "Ao trocar uma credencial já em uso:": "When replacing a credential already in use:",
  "quem já conectou a agenda vai precisar conectar de novo. O Google invalida as autorizações antigas quando o aplicativo muda — não há como evitar, e ninguém perde compromisso por isso.": "anyone who already connected their calendar will need to reconnect. Google invalidates old tokens when the OAuth app changes — there's no way around it, and no appointments are lost because of this.",
  "Nunca configurado por aqui.": "Never configured here.",
  "Credenciais do Google salvas.": "Google credentials saved.",
  "cifra indisponível nesta instalação (GUC app.nuvemshop_oauth_key ausente) — o segredo não foi gravado": "encryption unavailable on this installation (missing GUC app.nuvemshop_oauth_key) — secret was not saved",
  "Falta cadastrar o aplicativo do Google desta instalação. Leva um minuto e você faz por aqui mesmo.": "The Google app for this installation hasn't been registered yet. It takes a minute and you can do it right here.",
  "O que ele consulta antes de responder": "What it checks before replying",
  "Marque o material do seu negócio que este assistente pode ler. Ele procura ali antes de responder, em vez de improvisar — e cita de onde tirou.": "Select the business materials this assistant can read. It searches them before replying instead of improvising — and cites its sources.",
  "Você ainda não cadastrou nenhum material.": "You haven't added any materials yet.",
  "Comece pelo que ele mais vai precisar": "Start with what it will need most",
  "— as perguntas que se repetem, e a política que você mais explica.": "— frequently asked questions and the policy you explain most often.",
  "ainda não preparado": "not ready yet",
  "Sem nenhum material marcado, ele conversa normalmente — mas responde só com o que o modelo já sabe, e a ferramenta de busca nem entra na conversa dele.": "With no material selected, it chats normally — but answers only from what the model already knows, and the search tool isn't even loaded into its conversation.",
  "Você tem": "You have",
  "material": "material",
  "materiais": "materials",
  "no acervo e este assistente não lê nenhum. Ele vai responder de improviso sobre assuntos que já estão escritos.": "in your library and this assistant doesn't read any of them. It will improvise answers on topics you've already documented.",
  "O fluxo começa quando uma regra em Webhooks usa a ação «Iniciar fluxo de mensagem» apontando para este fluxo publicado.": "The flow starts when a rule in Webhooks uses the \"Start message flow\" action pointing to this published flow.",
  "Sai exatamente assim, sem IA. No laço,": "Sent verbatim, without AI. Inside a loop,",
  "{{volta}}": "{{volta}}",
  "{{voltas}}": "{{voltas}}",
  "viram o número da volta.": "become the iteration number.",
