  "Não consegui carregar os horários.": "Couldn't load available times.",
  "Os blocos ficam bloqueados até eu conseguir — é mais seguro que oferecer um horário que talvez não exista.": "Time blocks stay locked until I can load them — it's safer than offering a slot that might not exist.",
