  "Conta só a repergunta quase literal — reformulada com outras palavras escapa desta medida.": "Counts only near-verbatim repeat questions — rephrased questions aren't captured by this metric.",
  "Igual à mediana: há poucas esperas medidas no período para os dois se separarem.": "Same as the median: too few wait times were measured in this period for the two to diverge.",
  "O p90 é a experiência de quem espera mais — a mediana a esconde.": "The p90 reflects the experience of those who wait the longest — the median hides it.",
