  "Um material que você enviou não entrou na base de conhecimento": "A material you uploaded didn't make it into the knowledge base",
  "Aviso do assistente": "Assistant notice",
  "atenção": "attention",
  "O assistente prometeu algo ao cliente e ninguém ficou responsável": "The assistant promised something to the customer and no one was assigned",
  "Nesta conversa o assistente combinou algo com o cliente. Ele ainda não tem nenhuma capacidade marcada para registrar isso no sistema, então nada foi agendado nem anotado. Abra a conversa para ver o que foi combinado — e, na tela do assistente, marque o que ele pode fazer.": "In this conversation, the assistant agreed on something with the customer. It doesn't have any capability enabled to log this in the system yet, so nothing was scheduled or noted. Open the conversation to see what was agreed — and on the assistant screen, check what it's allowed to do.",
  "Nesta conversa o assistente combinou algo com o cliente e não registrou nenhum próximo passo para isso — não há retorno agendado. Abra a conversa, veja o que foi combinado e decida quem faz.": "In this conversation, the assistant agreed on something with the customer and didn't log any next step for it — there's no scheduled follow-up. Open the conversation, see what was agreed, and decide who handles it.",
  "Nesta conversa o assistente combinou algo com o cliente, e a parte que organiza o sistema não rodou neste atendimento. Nada foi agendado. Abra a conversa para ver o que foi combinado e decida quem faz.": "In this conversation, the assistant agreed on something with the customer, and the part that organizes the system didn't run during this interaction. Nothing was scheduled. Open the conversation to see what was agreed and decide who handles it.",
  "O agente já sabe": "The agent already knows",
