  "Material cadastrado. Estou preparando — em instantes o agente já sabe.": "Material added. Preparing it now — the agent will know it in a few moments.",
  "Material cadastrado. Ele fica esperando a chave da OpenAI para ser preparado.": "Material added. It is waiting for the OpenAI key to be prepared.",
