  "Trecho": "Excerpt",
  "Uma tela não folheia mil pedaços — o restante está no acervo e o agente alcança todos.": "One screen won't page through a thousand chunks — the rest is in the library and the agent can reach all of them.",
  "Perguntas e respostas": "Questions and answers",
  "As dúvidas que se repetem, com a resposta pronta. É o formato que o agente cita melhor, porque cada resposta chega inteira.": "Frequently asked questions with ready-made answers. This is the format the agent cites best because each answer arrives intact.",
  "Um texto do seu negócio — política de troca, tabela de preços, manual, contrato. Envie o arquivo (PDF, Markdown ou texto) ou cole o conteúdo.": "A document from your business — return policy, price list, manual, contract. Upload the file (PDF, Markdown, or text) or paste the content.",
