  "Meta Ads": "Meta Ads",
  "O desempenho das campanhas que estão trazendo gente para cá. Os números vêm da plataforma no momento em que você clica em Atualizar — nada fica guardado aqui.": "The performance of the campaigns bringing people here. Numbers are fetched live from the platform when you click Refresh — nothing is stored here.",
