  "Visualizações de vídeo": "Video views",
  "Instalações do app": "App installs",
  "A plataforma recusou o token de acesso — ele expirou ou foi revogado. Gere um novo em Configurações › Meta Ads.": "The platform rejected the access token — it has expired or been revoked. Generate a new one in Settings › Meta Ads.",
  "O token não tem permissão de leitura de anúncios (ads_read), ou não alcança esta conta. Refaça o token no Meta for Developers marcando essa permissão.": "The token does not have ad read permission (ads_read) or cannot access this account. Regenerate the token in Meta for Developers with that permission checked.",
  "A plataforma limitou as chamadas por excesso de consultas. Espere alguns minutos antes de atualizar de novo.": "The platform rate-limited requests due to too many queries. Wait a few minutes before refreshing again.",
  "A plataforma recusou um campo desta consulta. Isso é um problema do sistema, não da sua conta — avise quem mantém a instalação.": "The platform rejected a field in this query. This is a system issue, not your account — notify whoever maintains this installation.",
  "A chave de criptografia da instalação não está disponível, então o token guardado não pode ser lido. Isso é configuração do servidor.": "The installation's encryption key is unavailable, so the stored token cannot be read. This is a server configuration issue.",
  "Não consegui falar com a plataforma agora. Tente atualizar em instantes.": "Could not reach the platform right now. Try refreshing in a moment.",
  "Seu papel não permite ver os dados de anúncios.": "Your role does not allow viewing ad data.",
  "Conecte um token de acesso para o sistema ler o desempenho das suas campanhas e mostrá-lo em Análise › Meta Ads. É uma conexão só de leitura: nada é criado, pausado ou alterado na sua conta de anúncios.": "Connect an access token so the system can read your campaign performance and display it in Analytics › Meta Ads. This is a read-only connection: nothing is created, paused, or modified in your ad account.",
  "O token precisa da permissão ads_read. Gere-o no Meta for Developers, na sua conta de aplicativo, e cole abaixo — ele fica guardado criptografado e nunca é mostrado de volta.": "The token requires the ads_read permission. Generate it in Meta for Developers under your app account and paste it below — it is stored encrypted and never shown again.",
  "Para trocar apenas a conta padrão, deixe o campo do token em branco — o token guardado é mantido.": "To change only the default account, leave the token field blank — the saved token will be kept.",
  "Guardado — preencha só para trocar": "Saved — fill in only to replace",
  "Já existe um token guardado. Deixe em branco para mantê-lo, ou cole um novo para substituir.": "A token is already saved. Leave blank to keep it, or paste a new one to replace it.",
  "Precisa da permissão ads_read.": "Requires the ads_read permission.",
  "Conta padrão (opcional)": "Default account (optional)",
  "A conta que a tela de Meta Ads abre por padrão. Em branco, ela abre a primeira conta ativa que o token alcançar.": "The account that the Meta Ads screen opens by default. If left blank, it opens the first active account the token can access.",
  "Cole o token para poder salvar.": "Paste the token to save.",
  "Conta desconectada.": "Account disconnected.",
  "Desconectar apaga o token guardado. A tela de Meta Ads volta a pedir uma conexão, e nenhum dado histórico é perdido — nada é armazenado aqui.": "Disconnecting deletes the saved token. The Meta Ads screen will prompt for a connection again, and no historical data is lost — nothing is stored here.",
  "Não consegui desconectar agora.": "Could not disconnect right now.",
  "Você não está em nenhuma organização ativa.": "You are not in an active organization.",
  "Só um administrador da organização pode mudar esta conexão.": "Only an organization administrator can change this connection.",
  "Confirme o segundo fator para salvar esta mudança.": "Confirm your second factor to save this change.",
  "Esta instalação está sem a chave mestra de criptografia, e o token não foi gravado. Quem instalou o sistema precisa configurá-la — refazer o cadastro aqui não resolve.": "This installation is missing the master encryption key, so the token was not saved. Whoever installed the system needs to configure it — re-entering it here won't fix it.",
  "Não consegui gravar agora. Tente de novo em instantes.": "Could not save right now. Try again in a moment.",
  "Conversões": "Conversions",
  "Quando um negócio que veio de anúncio é marcado como ganho, o valor da venda volta para a plataforma que trouxe o cliente. É esse retorno que ensina o anúncio a procurar mais gente parecida com quem comprou.": "When a deal that came from an ad is marked as won, the sale value is sent back to the platform that brought the customer. That feedback teaches the ad to find more people like the buyer.",
  "O envio está pausado. As vendas continuam sendo registradas aqui, mas não vão para a plataforma enquanto isto estiver desligado.": "Sending is paused. Sales are still logged here, but they won't be sent to the platform while this is turned off.",
  "Modo de teste ligado: as vendas vão marcadas como teste e não contam para a otimização. Apague o código de teste quando terminar de conferir.": "Test mode enabled: sales are sent marked as test events and don't count toward optimization. Clear the test code when you're done verifying.",
  "Vendas que não foram reportadas": "Sales that were not reported",
  "reportadas com sucesso": "successfully reported",
  "Nenhuma pendência. Ou tudo que veio de anúncio foi reportado, ou ainda não fechou nenhuma venda com origem em anúncio.": "No pending items. Either everything from ads has been reported, or no ad-attributed sales have closed yet.",
  "Negócio": "Deal",
  "O que houve": "What happened",
