  "Só números. Você encontra no gerenciador de anúncios, na fonte de dados que recebe as conversões.": "Numbers only. You can find this in Ads Manager under the data source that receives conversions.",
  "Gravado. Deixe em branco para manter.": "Saved. Leave blank to keep.",
  "Cole o token gerado na plataforma": "Paste the token generated on the platform",
  "Guardado criptografado. Ele nunca volta para esta tela depois de salvo.": "Stored encrypted. It is never shown on this screen again after saving.",
  "Código de teste (opcional)": "Test code (optional)",
  "Enquanto preenchido, as vendas vão marcadas como teste e não contam para a otimização. Apague quando terminar de conferir.": "While filled in, sales are marked as test events and do not count toward optimization. Clear it once you are done verifying.",
