  "Apaga de vez as mensagens, conversas, negócios, contatos, agendamentos e pedidos desta organização. Serve para recomeçar os testes do zero antes de atender de verdade.": "Permanently deletes all messages, conversations, deals, contacts, appointments, and orders in this organization. Use this to restart your tests from scratch before going live.",
  "Continuam de pé: as pessoas da equipe, as configurações, os funis e etapas, os agentes de IA e os canais de WhatsApp já conectados.": "Kept intact: team members, settings, pipelines and stages, AI agents, and already connected WhatsApp channels.",
