  "Não foi possível guardar o segredo com segurança: a chave de cifra desta instalação não está ativa. Quem administra o servidor resolve rodando o update.sh, que gera e ativa a chave.": "Could not store the secret securely: the encryption key for this installation is not active. The server administrator can fix this by running update.sh, which generates and activates the key.",
  "Não foi possível guardar o segredo com segurança: a chave de cifra desta instalação não está ativa. Quem administra o servidor resolve rodando o update.sh, que gera e ativa a chave. Enquanto isso, você pode criar a fonte sem segredo.": "Could not store the secret securely: the encryption key for this installation is not active. The server administrator can fix this by running update.sh, which generates and activates the key. In the meantime, you can create the source without a secret.",
  "Não foi possível guardar o segredo do webhook com segurança: a chave de cifra desta instalação não está ativa. Quem administra o servidor resolve rodando o update.sh, que gera e ativa a chave.": "Could not store the webhook secret securely: the encryption key for this installation is not active. The server administrator can fix this by running update.sh, which generates and activates the key.",
  "Não foi possível guardar o segredo do webhook com segurança: a chave de cifra desta instalação não está ativa. Quem administra o servidor resolve rodando o update.sh, que gera e ativa a chave. Enquanto isso, você pode criar a ação sem segredo.": "Could not store the webhook secret securely: the encryption key for this installation is not active. The server administrator can fix this by running update.sh, which generates and activates the key. In the meantime, you can create the action without a secret.",
