  "O agente apenas lê a informação. Nada muda no sistema.": "The agent only reads information. Nothing changes in the system.",
  "O agente muda alguma coisa no sistema. Você consegue ver o que mudou e desfazer pela tela.": "The agent changes something in the system. You can see what changed and undo it on screen.",
  "O agente faz algo que sai do sistema ou não volta atrás — como falar com o cliente de verdade. Precisa ser ligado por você, uma a uma.": "The agent performs an external or irreversible action — like actually messaging the customer. You must enable these one by one.",
  "Abre a ficha completa de um cliente: dados de contato, histórico e por onde ele chegou até a empresa.": "Opens a customer's full profile: contact details, history, and how they found the company.",
  "Abre os detalhes de uma conversa: quem está atendendo, marcadores aplicados e há quanto tempo o cliente espera.": "Opens conversation details: who is handling it, applied tags, and how long the customer has been waiting.",
  "Abre os detalhes de uma oportunidade de venda: etapa atual, responsável, marcadores e valor do negócio.": "Opens sales opportunity details: current stage, owner, tags, and deal value.",
  "Abre um chamado e mostra tudo que aconteceu nele, inclusive a decisão que a pessoa tomou e o texto que ela escreveu ao decidir.": "Opens a ticket and shows everything that happened in it, including the person's decision and the note they wrote when deciding.",
  "Abre um endereço novo para o site da empresa mandar contatos direto para um funil. A partir daí ele passa a receber gente de fora sozinho.": "Creates a new endpoint so the company website can send contacts straight into a pipeline. From then on, it receives external leads automatically.",
  "Acrescenta uma coluna nova no fim do funil, quando o jeito de trabalhar da empresa tem um passo que ainda não está no quadro.": "Adds a new column at the end of the pipeline when the company's workflow has a step not yet on the board.",
  "Adiciona ou remove marcadores numa conversa, cliente ou oportunidade, para organizar e filtrar a operação depois.": "Adds or removes tags on a conversation, customer, or opportunity to organize and filter operations later.",
  "Agenda da equipe": "Team schedule",
  "Agendar um retorno para o cliente": "Schedule a customer follow-up",
  "Altera dados de uma oportunidade de venda: valor do negócio, responsável e informações colhidas na conversa.": "Updates sales opportunity details: deal value, owner, and information gathered during the conversation.",
  "Anota o que aconteceu num horário que já passou: a pessoa foi atendida, ou não apareceu.": "Logs what happened for a past appointment slot: whether the person was seen or didn't show up.",
  "Anotar uma regra aprendida": "Log a learned rule",
