  "O canal foi arquivado ou mudou. Escolha um atendimento em um canal disponível.": "The channel was archived or changed. Choose a conversation on an available channel.",
  "O acesso do solicitante ou o atendimento mudou. Confira o responsável e escolha um atendimento disponível.": "The requester's access or the conversation changed. Check the assignee and choose an available conversation.",
