  "Nunca mais perca um cliente por demora na resposta": "Never lose a customer to a slow reply again",
  "Todo o WhatsApp da sua empresa em uma tela só. Um atendente de IA responde na hora, com o que você ensinou, e passa a conversa para uma pessoa do time quando o assunto pede.": "All your company's WhatsApp chats on a single screen. An AI agent replies instantly using what you taught it, and hands the conversation over to a team member when needed.",
