  "Cancele quando quiser": "Cancel anytime",
  "A venda raramente se perde no preço. Ela se perde no silêncio.": "Sales are rarely lost over price. They're lost in silence.",
  "A resposta demora": "Replies take too long",
  "Quem pergunta às 22h só é atendido no dia seguinte. Até lá, já comprou de quem respondeu primeiro.": "Someone who asks a question at 10 PM only gets a reply the next day. By then, they've already bought from whoever replied first.",
  "A conversa se perde": "Conversations get lost",
  "Cada pessoa do time guarda um pedaço da história no próprio celular. Ninguém sabe o que já foi combinado.": "Each team member keeps a piece of the story on their own phone. Nobody knows what was already agreed upon.",
  "O retorno nunca acontece": "Follow-ups never happen",
  "O cliente disse “depois eu vejo” e ninguém voltou nele. É a venda mais barata da empresa, e ela evapora.": "The customer said “I'll get back to you” and no one followed up. That's the easiest sale in your company, and it just vanishes.",
  "Três passos, e o atendimento para de depender de memória": "Three steps, and customer service stops relying on memory",
  "Conecte o seu WhatsApp": "Connect your WhatsApp",
  "O mesmo número que a sua empresa já usa, por leitura de QR code. Ninguém troca de número e nenhuma conversa se perde.": "Use the same number your company already has by scanning a QR code. Nobody changes numbers and no conversation is lost.",
  "Ensine o atendente": "Train your agent",
  "Escreva o que a empresa faz, preço, prazo e as regras. O agente responde a partir disso — e só disso.": "Write down what your company does, pricing, timelines, and rules. The agent replies based on that — and only that.",
  "Acompanhe pelo funil": "Track it in the pipeline",
  "Cada conversa vira um card. Você vê quem está esperando, quem comprou e quem esfriou, sem perguntar a ninguém.": "Every conversation becomes a card. You see who's waiting, who bought, and who went cold, without having to ask anyone.",
  "O atendimento inteiro em um lugar só": "Your entire customer service in one place",
  "Uma caixa de entrada para o time todo": "One inbox for the whole team",
  "Todas as conversas em uma tela, com quem está atendendo o quê à vista de todos.": "All conversations on one screen, with full visibility into who is handling what.",
  "Agente de IA com a sua base de conhecimento": "AI agent powered by your knowledge base",
  "Ele responde pelo que você escreveu, não por achismo, e chama uma pessoa quando não sabe.": "It replies based on what you wrote, not guesswork, and loops in a human when it doesn't know the answer.",
  "Funil de vendas colado na conversa": "Sales pipeline built right into the chat",
  "Arraste o card, leia o histórico inteiro e pare de perguntar em que pé está cada cliente.": "Drag cards, read the full history, and stop asking where things stand with each customer.",
  "Retorno automático no tempo certo": "Automated follow-ups at the right time",
  "Quem parou de responder recebe uma mensagem de volta sem que ninguém precise lembrar disso.": "Anyone who stops replying gets a follow-up message automatically, without anyone having to remember.",
  "Relatórios de atendimento": "Customer service reports",
  "Tempo de resposta, volume por pessoa do time e o que de fato virou venda.": "Response time, volume per team member, and what actually turned into a sale.",
  "LGPD desde o primeiro dia": "LGPD-compliant from day one",
  "Dados isolados por empresa, registro de acesso e exclusão a pedido do titular.": "Isolated data per company, access logs, and data deletion upon request.",
