  "dias com tudo funcionando, sem cartão. Você só escolhe um plano quando decidir ficar.": "days with everything working, no card required. You only pick a plan when you decide to stay.",
  "Recomendado": "Recommended",
  "Começar agora": "Get started now",
  "O que costumam perguntar antes de assinar": "Common questions before subscribing",
  "Preciso trocar de número?": "Do I need to change my phone number?",
  "Não. Você conecta o número que a empresa já usa lendo um QR code, e as conversas seguem de onde pararam.": "No. You connect the number your company already uses by scanning a QR code, and conversations pick up right where they left off.",
  "A IA responde sozinha o tempo todo?": "Does the AI reply on its own all the time?",
  "Só até onde você deixar. Ela responde o que está na base de conhecimento e entrega a conversa a uma pessoa do time quando o assunto sai dali.": "Only as much as you allow. It answers what's in your knowledge base and hands the conversation over to a team member when the topic goes beyond that.",
  "O time todo consegue usar?": "Can my whole team use it?",
  "Sim. Cada pessoa entra com o próprio acesso e você decide o que cada uma pode ver e fazer.": "Yes. Each person logs in with their own account, and you decide what each member can see and do.",
  "E se eu quiser cancelar?": "What if I want to cancel?",
  "O cancelamento é um clique na própria tela de cobrança, sem falar com ninguém. O acesso continua até o fim do período já pago.": "Canceling takes one click right on the billing page, without talking to anyone. Your access continues until the end of your current billing period.",
  "Onde ficam os dados dos meus clientes?": "Where is my customers' data stored?",
  "Em base isolada por empresa, com registro de quem acessou o quê. Você pode exportar ou apagar os seus dados quando quiser.": "In an isolated database per company, with logs of who accessed what. You can export or delete your data whenever you want.",
  "A próxima pessoa que te chamar no WhatsApp merece resposta agora": "The next person who messages you on WhatsApp deserves an instant reply",
  "Crie a conta, conecte o número e veja o primeiro atendimento acontecer sozinho ainda hoje.": "Create your account, connect your number, and watch your first automated conversation happen today.",
  "Atendimento e vendas por WhatsApp": "Customer service and sales on WhatsApp",
  "Termos de uso": "Terms of Use",
  "Novo contato · 22h14": "New contact · 10:14 PM",
  "IA atendendo": "AI replying",
  "Oi! Vocês entregam hoje ainda? 😊": "Hi! Do you still deliver today? 😊",
  "Oi, Mariana! Entregamos sim. Pedidos fechados até as 23h saem amanhã cedo. Me diz o seu bairro que eu confirmo o prazo.": "Hi Mariana! Yes, we do. Orders placed before 11 PM go out first thing tomorrow morning. Tell me your neighborhood and I'll confirm the delivery window.",
  "Sou do centro 🙏": "I'm downtown 🙏",
  "No centro chega em até 2 horas. Quer que eu já reserve para você?": "Downtown deliveries arrive within 2 hours. Would you like me to reserve it for you now?",
