  "Sem spam. Um clique para sair, em qualquer e-mail.": "No spam. One-click unsubscribe in every email.",
  "Não foi possível inscrever agora. Tente de novo em instantes.": "Could not subscribe right now. Please try again in a moment.",
  "Pronto. Se houver novidade que valha o seu tempo, ela chega por e-mail.": "All set. Whenever there's an update worth your time, we'll send it to your inbox.",
  "Ainda pensando?": "Still thinking it over?",
  "Deixe seu e-mail. Mandamos o que aprendemos sobre atender por WhatsApp sem perder o cliente — e nada além disso.": "Leave your email. We'll share what we've learned about serving customers on WhatsApp without losing sales — and nothing else.",
  "Antes de ir: quer ver como isto funciona na prática?": "Before you go: want to see how this works in practice?",
  "Deixe seu e-mail e receba, em poucas mensagens, o que um atendimento automático de verdade responde — e o que ele nunca deve responder sozinho.": "Leave your email and get a few short messages showing what real automated customer service replies — and what it should never answer on its own.",
