  "Quais dados são tratados, por quanto tempo e quais são os seus direitos.": "What data is processed, for how long, and what your rights are.",
  "Transparência sobre como este sistema trata o seu dinheiro, os seus dados e o número da sua empresa.": "Transparency on how this system handles your money, your data, and your company's phone number.",
  "Ficou com dúvida sobre qualquer um destes pontos?": "Have questions about any of these points?",
  "Dúvida sobre planos, pedido de demonstração, problema com a conta ou relato de falha de segurança — tudo chega no mesmo lugar e é lido por gente.": "Questions about plans, demo requests, account issues, or security vulnerability reports — everything goes to the same place and is read by a real person.",
  "Mensagem recebida. A resposta vai para o e-mail que você informou.": "Message received. We'll reply to the email address you provided.",
  "Não foi possível enviar agora. Tente de novo em instantes.": "Could not send your message right now. Please try again in a moment.",
  "Esta instalação ainda não tem endereço de suporte configurado. Procure quem administra o sistema.": "This installation does not have a support address configured yet. Please contact your system administrator.",
  "Sair da lista": "Unsubscribe",
  "Ao confirmar, seu e-mail deixa de receber as nossas mensagens. Não é preciso entrar em conta nenhuma.": "By confirming, your email will stop receiving our messages. No need to log in to any account.",
  "Confirmar saída": "Confirm unsubscribe",
  "Pronto, você saiu.": "Done, you've been unsubscribed.",
  "Seu e-mail foi removido da lista. Nenhuma mensagem nova será enviada para ele.": "Your email has been removed from the list. No new messages will be sent to it.",
  "Este link não vale mais.": "This link is no longer valid.",
  "Pode ter sido cortado pelo seu programa de e-mail. Abra o link mais recente que recebeu, ou escreva para a gente que tiramos você da lista à mão.": "It may have been cut off by your email client. Open the most recent link you received, or write to us and we'll remove you from the list manually.",
  "Não deu para concluir agora.": "Could not complete this right now.",
  "Você continua na lista. Tente de novo em instantes — e se insistir em falhar, escreva para a gente.": "You are still on the list. Please try again in a moment — and if it keeps failing, write to us.",
  "Onze e quarenta e sete da noite. Um cliente pergunta o preço. Quem responde? Com a Atenza, o seu WhatsApp atende e vende vinte e quatro horas por dia.": "Eleven forty-seven at night. A customer asks for the price. Who replies? With Atenza, your WhatsApp serves customers and closes sales twenty-four hours a day.",
  "O agente de inteligência artificial responde na hora, com as informações do seu negócio: preço, estoque, horário, entrega. Quando a conversa pede uma pessoa, ela passa para a sua equipe, com todo o histórico. Ninguém pergunta tudo de novo.": "The artificial intelligence agent replies instantly with your business information: pricing, stock, hours, delivery. When the conversation calls for a human, it hands off to your team with the full chat history. Nobody has to ask the same questions all over again.",
  "Cada conversa vira uma oportunidade no funil. E o follow-up automático volta a falar com quem parou de responder. Precisa marcar horário? A Atenza agenda pela própria conversa, direto na sua agenda do Google.": "Every conversation becomes an opportunity in your pipeline. And automated follow-ups re-engage anyone who stops replying. Need to book an appointment? Atenza schedules it right inside the chat, straight to your Google Calendar.",
  "Vários atendentes no mesmo número, a API oficial do WhatsApp e os seus dados protegidos pela LGPD. Atenza: WhatsApp que atende e vende 24h. Teste sete dias sem cobrança.": "Multiple agents on the same number, the official WhatsApp API, and your data protected under LGPD. Atenza: WhatsApp that serves and sells 24/7. Try it free for seven days.",
  "Veja em menos de 1 minuto": "Watch in under 1 minute",
  "O que é a": "What is",
  "é uma plataforma brasileira de atendimento e vendas pelo WhatsApp que reúne, num único sistema, vários atendentes no mesmo número, agentes de inteligência artificial treinados com as informações do seu negócio, CRM com funil de vendas, follow-up automático, campanhas e agenda integrada ao Google.": "is a Brazilian WhatsApp customer service and sales platform that brings together, in a single system, multiple agents on the same phone number, AI agents trained on your business information, a CRM with a sales pipeline, automated follow-ups, campaigns, and Google Calendar integration.",
  "A conexão é pela API oficial do WhatsApp, da Meta, com integrações para Shopify, WooCommerce e Nuvemshop, além de API e webhooks para qualquer sistema. Atende empresas de todo o Brasil — lojas, clínicas, escolas, imobiliárias, escritórios e prestadores de serviço —, com planos mensais ou anuais e 7 dias sem cobrança para testar.": "It connects via Meta's official WhatsApp API, with integrations for Shopify, WooCommerce, and Nuvemshop, plus an API and webhooks for any system. It serves businesses across Brazil — stores, clinics, schools, real estate agencies, offices, and service providers — with monthly or annual plans and a 7-day free trial.",
